package io.github.diodeme.ji.export;

import io.github.diodeme.ji.artifact.ArtifactReference;
import java.util.List;

/** Single-session readable export options. Artifact links are opt-in. */
public record ExportOptions(List<ArtifactReference> artifacts, boolean includeArtifactLinks) {
    public ExportOptions {
        artifacts = List.copyOf(artifacts);
        if (!includeArtifactLinks && !artifacts.isEmpty()) {
            throw new IllegalArgumentException("artifact references require includeArtifactLinks");
        }
    }

    public static ExportOptions withoutArtifacts() {
        return new ExportOptions(List.of(), false);
    }
}
